<section class="content-header"><h1><i class="fa fa-clock-o"></i> Ventas por horario</h1></section><section class="content">
<div class="box box-primary no-print"><div class="box-body"><form method="get" class="form-inline"><label>Desde</label> <input type="date" name="desde" class="form-control" value="<?php echo html_escape($filtros['desde']);?>"> <label>Hasta</label> <input type="date" name="hasta" class="form-control" value="<?php echo html_escape($filtros['hasta']);?>"> <select name="ruta_id" class="form-control"><option value="0">Todas las rutas</option><?php foreach($listas['rutas'] as $r):?><option value="<?php echo $r['ruta_id'];?>" <?php echo $filtros['ruta_id']==$r['ruta_id']?'selected':'';?>><?php echo html_escape($r['ruta_nombre']);?></option><?php endforeach;?></select> <select name="vehiculo_id" class="form-control"><option value="0">Todos los vehículos</option><?php foreach($listas['vehiculos'] as $v):?><option value="<?php echo $v['vehiculo_id'];?>" <?php echo $filtros['vehiculo_id']==$v['vehiculo_id']?'selected':'';?>><?php echo html_escape($v['vehiculo_placa'].' '.$v['vehiculo_marca']);?></option><?php endforeach;?></select> <button class="btn btn-primary"><i class="fa fa-search"></i> Generar</button></form></div></div>
<div class="box"><div class="box-header"><h3 class="box-title">Ocupación por hora programada de salida</h3><div class="pull-right no-print"><button onclick="window.print()" class="btn btn-default btn-sm"><i class="fa fa-print"></i> Imprimir</button> <a class="btn btn-success btn-sm" href="<?php echo site_url('reporte_ventas_horario/csv').'?'.http_build_query($filtros);?>"><i class="fa fa-file-excel-o"></i> Excel/CSV</a></div></div><div class="box-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Horario</th><th class="text-right">Viajes</th><th class="text-right">Capacidad ofrecida</th><th class="text-right">Pasajeros vendidos</th><th>Ocupación</th><th class="text-right">Ingresos</th></tr></thead><tbody><?php foreach($filas as $r):$pct=(float)$r['ocupacion'];?><tr><td><b><?php echo html_escape($r['horario']);?></b></td><td class="text-right"><?php echo number_format($r['viajes'],0,',','.');?></td><td class="text-right"><?php echo number_format($r['capacidad'],0,',','.');?></td><td class="text-right"><?php echo number_format($r['pasajeros'],0,',','.');?></td><td style="min-width:220px"><div class="progress" style="margin-bottom:0"><div class="progress-bar" role="progressbar" aria-valuenow="<?php echo $pct;?>" aria-valuemin="0" aria-valuemax="100" style="width:<?php echo min(100,$pct);?>%"><b><?php echo number_format($pct,1,',','.');?>%</b></div></div></td><td class="text-right"><b>Bs <?php echo number_format($r['ingresos'],2,',','.');?></b></td></tr><?php endforeach;?></tbody></table></div><p class="text-muted"><small>La ocupación es ponderada: pasajeros vendidos ÷ capacidad total ofrecida en ese horario. Se excluyen viajes cancelados y reservas.</small></p></div></div></section><style media="print">.no-print,.main-header,.main-sidebar,.content-header,.main-footer{display:none!important}.content-wrapper{margin-left:0!important}.content{padding:0!important}</style>
